CREATE OR REPLACE PROCEDURE lab.raise_dept (p_dept numeric, p_pct numeric, OUT p_updated numeric)
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  l_ids numeric[];
  l_id  numeric;
BEGIN
  SELECT array_agg(emp_id) INTO l_ids FROM emp WHERE dept_id = p_dept;
  FOREACH l_id IN ARRAY coalesce(l_ids, '{}') LOOP
    UPDATE emp SET salary = round(salary * (1 + p_pct / 100), 2) WHERE emp_id = l_id;
  END LOOP;
  GET DIAGNOSTICS p_updated = ROW_COUNT;
END;
$$;
